!function(r){function n(n){for(var t,e,o=n[0],c=n[1],u=n[2],s=0,g=[];s<o.length;s++)e=o[s],Object.prototype.hasOwnProperty.call(a,e)&&a[e]&&g.push(a[e][0]),a[e]=0;for(t in c)Object.prototype.hasOwnProperty.call(c,t)&&(r[t]=c[t]);for(m&&m(n);g.length;)g.shift()();return i.push.apply(i,u||[]),p()}function p(){for(var r,n=0;n<i.length;n++){for(var p,e=i[n],o=!0,c=1;c<e.length;c++)p=e[c],0!==a[p]&&(o=!1);o&&(i.splice(n--,1),r=t(t.s=e[0]))}return r}function t(n){if(e[n])return e[n].exports;var p=e[n]={i:n,l:!1,exports:{}};return r[n].call(p.exports,p,p.exports,t),p.l=!0,p.exports}var e={},a={6:0},i=[];t.m=r,t.c=e,t.d=function(r,n,p){t.o(r,n)||Object.defineProperty(r,n,{enumerable:!0,get:p})},t.r=function(r){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(r,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(r,"__esModule",{value:!0})},t.t=function(r,n){if(1&n&&(r=t(r)),8&n)return r;if(4&n&&"object"==typeof r&&r&&r.__esModule)return r;var p=Object.create(null);if(t.r(p),Object.defineProperty(p,"default",{enumerable:!0,value:r}),2&n&&"string"!=typeof r)for(var e in r)t.d(p,e,function(n){return r[n]}.bind(null,e));return p},t.n=function(r){var n=r&&r.__esModule?function(){return r.default}:function(){return r};return t.d(n,"a",n),n},t.o=function(r,n){return Object.prototype.hasOwnProperty.call(r,n)},t.p="";var o=window.webpackJsonp=window.webpackJsonp||[],c=o.push.bind(o);o.push=n,o=o.slice();for(var u=0;u<o.length;u++)n(o[u]);var m=c;i.push([68,0]),p()}({68:function(r,n,p){"use strict";p.r(n);var t=p(0);Object(t.a)("ru","army",p(69),p(1))},69:function(r){r.exports=JSON.parse('{"category":[{"name":"苏联","link":"ru_shortcut"},{"name":"陆战武器","link":"ru_army"},{"name":"火炮","link":"ru_army#ru_army_cannon"}],"model":"苏军高射炮","description":"<h6>综述：</h6><p>二战期间，苏军装备的高射炮有1940式（72-K）25毫米高射炮、 1939式（61-K）37毫米高射炮、1934式（21-K）45毫米高射炮和1939式（52-K）85毫米高射炮等多个型号。</p><p>1940式（72-K）25毫米高射炮研制于1939年，虽然弹道性能较先进，但因口径较小，多用于步兵团的防空，生产数量为4800多门。</p><p>1934式（21-K）45毫米高射炮则是用M1932（19-K）反坦克炮改装，专为海军使用，生产数量只有2000多门。</p><p>1939式（61-K）37毫米高射炮则是苏军二战中主要的轻型防空炮，也是苏军应用广泛的一种武器，它通常用来对付德军的俯冲轰炸机和低空飞行的运输机、轰炸机、侦察机等，同时也大量用于地面作战，对付德军的轻型坦克与装甲车，在东线的各个战场上到处都可见到其身影。二战期间，该型高射炮一共生产了近2万门。</p><p>1939式（52-K）85毫米高射炮是苏军在二战中的重型防空炮，二战前就装备苏军，主要用来对付飞行在中高海拔高度的飞机，也可作为有效的反坦克武器对抗德国中、重型坦克，由于该炮口径大，且有优良的内外弹道性能，因此到二战结束后仍在服役。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"imgs/ru/army/ru_army_cannonAA_10.jpg","description":"<h6>1939式（61-K）37mm高射炮</h6><p></p><p>基本技术数据：</p><p>火炮口径：37毫米；</p><p>火炮全长：6.036米；</p><p>火炮总重：2100千克；</p><p>炮口初速：880米/秒；</p><p>火炮射速：理论射速160～180发/分，实际战斗射速80～120发/分；</p><p>最大射程：8500米；</p><p>可使用弹药：曳光杀伤榴弹、曳光装甲榴弹。</p>","caption":""},{"image":"imgs/ru/army/ru_army_cannonAA_11.jpg","description":"<h6>1939式（52-K）85mm高射炮</h6><p></p><p>基本技术数据：</p><p>火炮口径：85毫米；</p><p>火炮全长：7.05米；</p><p>火炮总重：4500千克；</p><p>炮口初速：792米/秒；</p><p>最大射速：12发/分；</p><p>最大射程：15650米，有效射程：10500米；</p><p>可使用弹药：杀伤榴弹、穿甲弹和曳光高速穿甲弹。</p>","caption":""}],"part2title":"战场上的苏军37mm与85mm高射炮","part2description":"","part2content":[{"image":"imgs/ru/army/ru_army_cannonAA_20.jpg","description":"二战东线苏联战场，苏军一处正在对空警戒的1939式（61-K）37毫米高射炮阵地。该炮采用类似机关炮的弹夹设计，每次装填能够速射5发炮弹，而苏军一个37毫米高炮连通常装备数为4门，防空作战时会组成一个射击方阵，因而能形成一个密集的对空火力，在这个火力范围内，进行低空轰炸的德军战机通常难以逃脱。","caption":""},{"image":"imgs/ru/army/ru_army_cannonAA_21.jpg","description":"二战期间，列宁格勒城中苏军一门1939式（61-K）37毫米高射炮正准备迎击随时来犯的德军战机。在二战战场上，德军采用低空俯冲轰炸的斯图卡轰炸机经常对苏军造成极大杀伤，而37毫米高射炮正是苏军对抗低空德军战机的强力武器。据不完全统计，该型炮在二战期间共击落德军战机14000多架，战果极为惊人。","caption":""},{"image":"imgs/ru/army/ru_army_cannonAA_22.jpg","description":"二战东线苏联战场，部署在城市广场上的一门苏军1939式（61-K）37毫米高射炮正在进行地面作战，抗击进攻的德军坦克。1939式37毫米高射炮使用穿甲弹能在500米的射击距离上击穿46毫米厚的钢板。对于苏德战争初期的德军38（t）和Ⅲ号等轻型坦克，由于正面装甲不超过50毫米，在较近距离内，该炮的穿甲能力完全可以将其击穿。在莫斯科保卫战中，因缺少反坦克火炮，苏军曾将大量储备的1939式37毫米高射炮配给前线部队加入反坦克作战。德军有资料统计，在沃洛科拉姆斯克保卫战期间，德军累计损失的80辆坦克中，有60辆是被苏军这种高射炮击伤或击毁的。","caption":""},{"image":"imgs/ru/army/ru_army_cannonAA_23.jpg","description":"二战东线苏联战场，苏军部署在城市街道废墟上的一门1939式（61-K）37毫米高射炮，炮兵们正全神贯注地注视着天空，随时准备迎击德军战机。","caption":""},{"image":"imgs/ru/army/ru_army_cannonAA_24.jpg","description":"1945年，二战东线德国战场，在一处苏军1939式（61-K）37毫米高射炮阵地上，处于对空观察与临战状态的苏军炮兵们，疑似为一张摆拍照片。","caption":""},{"image":"imgs/ru/army/ru_army_cannonAA_25.jpg","description":"1941年底，二战东线苏联战场，在列宁格勒保卫战中部署在涅瓦河沿岸的苏军一门1939式（52-K）85毫米重型高射炮。苏军的85毫米高射炮主要用于保卫车站、桥梁等重要目标，也用于城市保卫战的防空，其最大射程可达15.65千米，能打击中高空飞行的德军轰炸机。","caption":""},{"image":"imgs/ru/army/ru_army_cannonAA_26.jpg","description":"1941年秋季，二战东线苏联战场哈尔科夫地区，一门用树枝进行了伪装的1939式（52-K）85毫米重型高射炮阵地上，苏军炮兵正紧张地投入对空作战。1941年10月，德国第17集团军进攻哈尔科夫，苏联第18集团军与德军第55军进行了长达五天的巷战，双方都损失巨大，最终于10月底，这个苏联工业中心被德军攻占。","caption":""},{"image":"imgs/ru/army/ru_army_cannonAA_27.jpg","description":"1941年夏天，二战东线苏联战场敖德萨附近地区，一处正准备迎击德军战机的苏军1939式（52-K）85毫米重型高射炮阵地。","caption":""},{"image":"imgs/ru/army/ru_army_cannonAA_28.jpg","description":"1941年秋季，二战东线苏联战场，一门苏军1939式（52-K）85毫米重型高射炮正在向远方德军坦克射击。该炮性能接近德军88毫米高炮水平，在发射高爆穿甲弹时，可在1000米距离击穿102毫米装甲，发射高速穿甲弹时，可击穿130毫米装甲，因此除了具备防空作战能力外，也能打击地面的重装甲目标，但苏军却较少将其用于反坦克任务。","caption":""},{"image":"imgs/ru/army/ru_army_cannonAA_29.jpg","description":"1942年，二战东线苏联战场，部署在苏联某城市郊外的一处1939式（52-K）85毫米重型高射炮阵地。","caption":""}]}')}});